# Lesson program for evidence-based planning and dependency scheduling.
# Read: phases/14-agent-engineering/44-plan-from-evidence/docs/en.md
# Reference: PERT, U.S. Navy Special Projects Office, 1958.
# Reference: CPM, Kelley and Walker, Eastern Joint Computer Conference, 1959.
# Run this file to generate outputs/evidence-plan.json.
from __future__ import annotations

import json
from dataclasses import asdict, dataclass
from pathlib import Path


@dataclass(frozen=True)
class WorkItem:
    id: str
    change: str
    evidence: tuple[str, ...]
    depends_on: tuple[str, ...]
    proof: str


def validate(items: list[WorkItem]) -> list[str]:
    issues: list[str] = []
    ids = [item.id for item in items]
    if len(ids) != len(set(ids)):
        issues.append("work item ids must be unique")
    known = set(ids)
    has_unknown_dependency = False
    for item in items:
        if not item.evidence:
            issues.append(f"{item.id} has no repository evidence")
        if not item.proof.strip():
            issues.append(f"{item.id} has no proof command")
        missing = sorted(set(item.depends_on) - known)
        if missing:
            has_unknown_dependency = True
            issues.append(f"{item.id} depends on unknown items: {', '.join(missing)}")
    if not has_unknown_dependency:
        try:
            execution_waves(items)
        except ValueError as error:
            issues.append(str(error))
    return issues


def execution_waves(items: list[WorkItem]) -> list[list[str]]:
    known = {item.id for item in items}
    for item in items:
        missing = sorted(set(item.depends_on) - known)
        if missing:
            raise ValueError(f"{item.id} depends on unknown items: {', '.join(missing)}")
    remaining = {item.id: set(item.depends_on) for item in items}
    waves: list[list[str]] = []
    completed: set[str] = set()
    while remaining:
        ready = sorted(item_id for item_id, deps in remaining.items() if deps <= completed)
        if not ready:
            cycle = ", ".join(sorted(remaining))
            raise ValueError(f"dependency cycle among: {cycle}")
        waves.append(ready)
        completed.update(ready)
        for item_id in ready:
            del remaining[item_id]
    return waves


def plan_document(items: list[WorkItem]) -> dict:
    issues = validate(items)
    return {
        "status": "ready" if not issues else "blocked",
        "issues": issues,
        "waves": execution_waves(items) if not issues else [],
        "items": [asdict(item) for item in items],
    }


def example() -> list[WorkItem]:
    return [
        WorkItem("contract", "Define duplicate-email behavior", ("tests/test_accounts.py:44",), (), "review contract"),
        WorkItem("implementation", "Reject normalized duplicates", ("app/accounts.py:18",), ("contract",), "python3 -m unittest tests.test_accounts"),
        WorkItem("docs", "Document the 409 response", ("docs/api.md:72",), ("contract",), "python3 scripts/check_links.py"),
        WorkItem("integration", "Run the complete acceptance gate", ("pyproject.toml:31",), ("implementation", "docs"), "python3 -m unittest"),
    ]


def main() -> None:
    output = Path(__file__).resolve().parents[1] / "outputs" / "evidence-plan.json"
    output.write_text(json.dumps(plan_document(example()), indent=2) + "\n", encoding="utf-8")
    print(output.read_text(encoding="utf-8"))


if __name__ == "__main__":
    main()

// Lesson: Build an Evidence-Backed Execution Plan (phase 14 / lesson 44)
// TypeScript port of code/main.py. Node standard library only.
// Source: phases/14-agent-engineering/44-plan-from-evidence/docs/en.md
// Run: npx tsx phases/14-agent-engineering/44-plan-from-evidence/code/main.ts

import { readFileSync, realpathSync, writeFileSync } from "node:fs";
import { dirname, join } from "node:path";

class WorkItem {
  constructor(
    readonly id: string,
    readonly change: string,
    readonly evidence: readonly string[],
    readonly depends_on: readonly string[],
    readonly proof: string,
  ) {
    Object.freeze(this);
  }
}

interface PlanDocument {
  status: string;
  issues: string[];
  waves: string[][];
  items: { id: string; change: string; evidence: string[]; depends_on: string[]; proof: string }[];
}

function missingDeps(item: WorkItem, known: Set<string>): string[] {
  return [...new Set(item.depends_on.filter((dep) => !known.has(dep)))].sort();
}

function validate(items: WorkItem[]): string[] {
  const issues: string[] = [];
  const ids = items.map((item) => item.id);
  if (ids.length !== new Set(ids).size) {
    issues.push("work item ids must be unique");
  }
  const known = new Set(ids);
  let hasUnknownDependency = false;
  for (const item of items) {
    if (item.evidence.length === 0) {
      issues.push(`${item.id} has no repository evidence`);
    }
    if (!item.proof.trim()) {
      issues.push(`${item.id} has no proof command`);
    }
    const missing = missingDeps(item, known);
    if (missing.length > 0) {
      hasUnknownDependency = true;
      issues.push(`${item.id} depends on unknown items: ${missing.join(", ")}`);
    }
  }
  if (!hasUnknownDependency) {
    try {
      executionWaves(items);
    } catch (error) {
      issues.push((error as Error).message);
    }
  }
  return issues;
}

function executionWaves(items: WorkItem[]): string[][] {
  const known = new Set(items.map((item) => item.id));
  for (const item of items) {
    const missing = missingDeps(item, known);
    if (missing.length > 0) {
      throw new Error(`${item.id} depends on unknown items: ${missing.join(", ")}`);
    }
  }
  const remaining = new Map<string, Set<string>>();
  for (const item of items) {
    remaining.set(item.id, new Set(item.depends_on));
  }
  const waves: string[][] = [];
  const completed = new Set<string>();
  while (remaining.size > 0) {
    const ready = [...remaining.entries()]
      .filter(([, deps]) => [...deps].every((dep) => completed.has(dep)))
      .map(([itemId]) => itemId)
      .sort();
    if (ready.length === 0) {
      const cycle = [...remaining.keys()].sort().join(", ");
      throw new Error(`dependency cycle among: ${cycle}`);
    }
    waves.push(ready);
    for (const itemId of ready) {
      completed.add(itemId);
      remaining.delete(itemId);
    }
  }
  return waves;
}

function planDocument(items: WorkItem[]): PlanDocument {
  const issues = validate(items);
  return {
    status: issues.length === 0 ? "ready" : "blocked",
    issues,
    waves: issues.length === 0 ? executionWaves(items) : [],
    items: items.map((item) => ({
      id: item.id,
      change: item.change,
      evidence: [...item.evidence],
      depends_on: [...item.depends_on],
      proof: item.proof,
    })),
  };
}

function example(): WorkItem[] {
  return [
    new WorkItem("contract", "Define duplicate-email behavior", ["tests/test_accounts.py:44"], [], "review contract"),
    new WorkItem("implementation", "Reject normalized duplicates", ["app/accounts.py:18"], ["contract"], "python3 -m unittest tests.test_accounts"),
    new WorkItem("docs", "Document the 409 response", ["docs/api.md:72"], ["contract"], "python3 scripts/check_links.py"),
    new WorkItem("integration", "Run the complete acceptance gate", ["pyproject.toml:31"], ["implementation", "docs"], "python3 -m unittest"),
  ];
}

function main(): void {
  const output = join(dirname(realpathSync(__dirname)), "outputs", "evidence-plan.json");
  writeFileSync(output, JSON.stringify(planDocument(example()), null, 2) + "\n", "utf8");
  console.log(readFileSync(output, "utf8"));
}

main();

